import{_ as l,o as t,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"RGW S3: Feature Progress, Limitations & Testing - Robin H Johnson & Ali Maredia,","description":"","frontmatter":{"title":"RGW S3: Feature Progress, Limitations & Testing - Robin H Johnson & Ali Maredia,","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","RGW","S3 API","Testing","Performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/RGW_S3_-_Feature_Progress_Limitations_Testing_-_Robin_H_Johnson_Ali_Maredia.md","filePath":"posts/2019/RGW_S3_-_Feature_Progress_Limitations_Testing_-_Robin_H_Johnson_Ali_Maredia.md","lastUpdated":1780459816000}'),e={name:"posts/2019/RGW_S3_-_Feature_Progress_Limitations_Testing_-_Robin_H_Johnson_Ali_Maredia.md"};function n(r,i,_,a,p,g){return t(),o("div",null,[...i[0]||(i[0]=[s("<p>会议纪要：</p><p><strong>会议主题</strong>： Ceph RGW中的S3功能及其局限性</p><p><strong>会议参与者</strong>： Robin（Digital Ocean）、Allie（Red Hat）</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>S3术语回顾</strong>：</p><ul><li>回顾了S3协议、规范、AWS服务以及Ceph RGW（Rados Gateway）的定义。</li></ul></li><li><p><strong>S3功能与局限性</strong>：</p><ul><li>讨论了Ceph RGW在S3功能方面的局限性，例如S3库存、分析、生命周期管理等。</li><li>提到了S3测试套件和其局限性，包括不覆盖RGW后端特定功能、不用于性能测试等。</li></ul></li><li><p><strong>RGW对象布局与删除</strong>：</p><ul><li>解释了RGW如何将对象布局到Redis中，以及删除对象时的同步和异步过程。</li></ul></li><li><p><strong>垃圾回收</strong>：</p><ul><li>分析了垃圾回收设计的问题，例如单线程运行、对OSD的读写压力很大、缺乏监控等。</li></ul></li><li><p><strong>生命周期管理</strong>：</p><ul><li>讨论了生命周期管理存在的问题，如元数据访问昂贵、扫描速度慢、缺乏监控等。</li></ul></li><li><p><strong>S3测试的未来</strong>：</p><ul><li>提出了改进S3测试套件的计划，包括迁移到Python 3、添加更多测试用例、支持其他SDK等。</li></ul></li><li><p><strong>S3测试的社区贡献</strong>：</p><ul><li>鼓励社区贡献S3测试套件，希望所有提供商都能使用并共同改进。</li></ul></li><li><p><strong>S3 API的扩展</strong>：</p><ul><li>考虑扩展S3 API，以提供用户统计、桶统计、用户配额等信息。</li></ul></li></ol><p><strong>会议决定事项</strong>：</p><ol><li>修复垃圾回收设计中的问题。</li><li>优化生命周期管理。</li><li>将S3测试套件迁移到pytest。</li><li>添加更多测试用例，覆盖更多SDK。</li><li>鼓励社区贡献S3测试套件。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Robin和Allie将负责修复垃圾回收设计中的问题。</li><li>Robin和Allie将负责优化生命周期管理。</li><li>Robin和Allie将负责将S3测试套件迁移到pytest。</li><li>Robin和Allie将负责添加更多测试用例，覆盖更多SDK。</li><li>Robin和Allie将鼓励社区贡献S3测试套件。</li></ol>",9)])])}const R=l(e,[["render",n]]);export{u as __pageData,R as default};
